function alignGrid(items) {
  // Phase 1: READ all layout values
  const rects = Array.from(items).map(item => ({
    height: item.getBoundingClientRect().height,
    width: item.getBoundingClientRect().width
  }));

  // Phase 2: WRITE all mutations
  items.forEach((item, i) => {
    item.style.transform = `translateY(${rects[i].height}px)`;
    item.style.width = rects[i].width + 'px';
  });

  // Phase 3: READ again only if needed
  const newRects = Array.from(items).map(item =>
    item.getBoundingClientRect()
  );
}

// Result: 1 read pass + 1 write pass + 1 final read pass
// 100 items = 3 layout calculations instead of 200

// React-specific tip: avoid refs inside render for layout reads
